export function getAudioFileForDevotion(devotionTitle: string): string {
  return devotionTitle
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim();
}

export function hasAudioForDevotion(devotionTitle: string): boolean {
  return AVAILABLE_AUDIO_FILES.has(getAudioFileForDevotion(devotionTitle));
}
